<script setup lang="ts">
/**
 * The CrawlStat owl.
 *
 * Inlined rather than loaded through `<img src>` for one concrete reason:
 * `currentColor` does not cross an image boundary. An `<img>` renders the SVG
 * in its own document, where `currentColor` resolves to black — which is how
 * the mark ended up as a dark smudge on a dark header. Inline, it inherits the
 * surrounding text colour and is correct on every background without a second
 * file or a filter hack.
 *
 * It also removes a request and some layout shift: the logo is in the HTML by
 * the time the first paint happens.
 *
 * `wordmark` is the full wingspan; `mark` is the head alone, for sizes below
 * about 60px where the wingspan's double strokes stop resolving.
 *
 * It is always embossed: lines the colour of the page, lit from the top left
 * like every raised surface on the site. Below 100px the lines are under a
 * pixel thick, so small owls get a deeper line and a tighter shadow to stay
 * legible.
 */
const props = withDefaults(defineProps<{ variant?: 'wordmark' | 'mark'; height?: number }>(), {
  variant: 'wordmark',
  height: 34,
})
const size = computed(() => (props.height >= 100 ? 'lg' : 'sm'))
</script>

